cd "/Volumes/My Shared Files" && python3 - <<'EOF'
p='work/solar-implosion.html'
s=open(p).read()
a=s.index("// ---------- singularity core ----------")
b=s.index("// ---------- shockwave shell + ring ----------")
new='''// ---------- singularity core (screen-relative billboard: same look at any resolution, no point-size caps) ----------
const coreMat=new THREE.ShaderMaterial({
  transparent:true,depthWrite:false,depthTest:false,blending:THREE.AdditiveBlending,
  uniforms:{uSize:{value:40},uInt:{value:.5},uRes:{value:new THREE.Vector2(innerWidth,innerHeight)}},
  vertexShader:`uniform float uSize; uniform vec2 uRes; varying vec2 vQ;
    void main(){
      vec4 c=projectionMatrix*modelViewMatrix*vec4(0.,0.,0.,1.);
      float px=uSize*min(uRes.x,uRes.y)/360.;           // diameter in css px, tuned at 360px
      c.xy+=vec2(position.x*2.*px/uRes.x,position.y*2.*px/uRes.y)*c.w;
      vQ=position.xy*2.; gl_Position=c;}`,
  fragmentShader:`uniform float uInt; varying vec2 vQ; void main(){
    float r=length(vQ);
    float core=exp(-r*r*14.)+.35*exp(-r*3.5);
    vec3 col=mix(vec3(1.,.5,.2),vec3(1.),exp(-r*r*12.));
    gl_FragColor=vec4(col*core*uInt*step(r,1.),1.);}`
});
const core=new THREE.Mesh(new THREE.PlaneGeometry(1,1),coreMat); core.frustumCulled=false; scene.add(core);

'''
s=s[:a]+new+s[b:]
s=s.replace("mat.uniforms.uScale.value=innerHeight*renderer.getPixelRatio();\n});","mat.uniforms.uScale.value=innerHeight*renderer.getPixelRatio();\n  coreMat.uniforms.uRes.value.set(innerWidth,innerHeight);\n});")
s=s.replace("const dist=48-10*Math.sin(ang)-9*tens+12*burst;","const wide=Math.min(2,Math.max(1,Math.pow(1.5/camera.aspect,.7))); // frame the whole system on tall screens\n  const dist=(48-10*Math.sin(ang)-9*tens+12*burst)*wide;")
open(p,'w').write(s)
